package delivery
import("testing";"github.com/google/uuid";"photoeditor/backend/internal/auth")
func TestDeliveryExactPresetInventoryIsOwnedAndComplete(t *testing.T){id:=uuid.New();request:=CreateRequest{ProjectID:uuid.New(),SnapshotID:uuid.New(),Name:"Export",Policy:Policy{RequiredPresets:[]uuid.UUID{id},OptionalPresets:[]uuid.UUID{},MetadataPolicy:"strip",Provenance:"off"},ExpectedPresetSHA:map[uuid.UUID]string{id:"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}};who:=auth.Identity{UserID:uuid.New(),SessionID:uuid.New()};intent,err:=FreezeCreateIntent(uuid.New(),who,request,"export-key");if err!=nil{t.Fatal(err)};request.ExpectedPresetSHA[id]="changed";if intent.Request().ExpectedPresetSHA[id]=="changed"{t.Fatal("caller changed immutable intent")};owned:=intent.Request();owned.ExpectedPresetSHA[id]="changed";if intent.Request().ExpectedPresetSHA[id]=="changed"{t.Fatal("request copy shares pin map")};if _,err:=FreezeCreateIntent(uuid.New(),who,request,"export-key");err==nil{t.Fatal("invalid pin admitted")}}
